/** A stored draft: an object or nothing. Its fields are read by the creator itself. */
export function readCreatorDraft(value: unknown): Record<string, unknown> | null {
    return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : null
}

/** The presets that have an id, a name and an object for data; the rest are dropped. */
export function readCreatorPresets(value: unknown): Array<{ id: string; name: string; data: Record<string, unknown> }> {
    if (!Array.isArray(value)) return []
    return value.flatMap((item) => {
        const preset = item as { id?: unknown; name?: unknown; data?: unknown }
        const id = typeof preset?.id === 'string' ? preset.id.trim() : ''
        const name = typeof preset?.name === 'string' ? preset.name.trim() : ''
        const data = readCreatorDraft(preset?.data)
        return id && name && data ? [{ id, name, data }] : []
    })
}

/** A level 1–20, or `'none'`; anything else is 1. */
export function readCreatorLevel(value: unknown): number | 'none' {
    if (value === 'none') return 'none'
    const n = typeof value === 'number' ? value : Number.parseInt(String(value ?? ''), 10)
    return Number.isFinite(n) && n >= 1 ? Math.min(20, Math.floor(n)) : 1
}

const CREATOR_GEAR_TIERS = ['auto', 'mundane', 'low', 'standard', 'well_equipped', 'heroic', 'none']

export function readCreatorGearTier(value: unknown): string {
    return CREATOR_GEAR_TIERS.includes(String(value)) ? String(value) : 'auto'
}

/** What the file holds. Versioned so a later shape can migrate. */
export interface PrefsRecord extends UiPrefs {
    version: 1
}

export const PREFS_VERSION = 1

/**
 * Read a stored file back into a full set of preferences.
 *
 * Every key is validated by type rather than trusted: this is a small file that
 * a user may well open, and a `"false"` string turning the cards off forever
 * with no error would be a miserable thing to debug.
 */
/**
 * Read an ownership map defensively.
 *
 * This file is a user's to edit, and a malformed entry here decides which books
 * an undo may delete. A chat with no usable names is dropped rather than kept
 * as an empty list that would later read as "this campaign owns nothing".
 */
export function readCampaignBooks(source: unknown): Record<string, string[]> {
    const owned: Record<string, string[]> = {}
    if (!source || typeof source !== 'object') return owned
    for (const [chatId, books] of Object.entries(source as Record<string, unknown>)) {
        if (!chatId || !Array.isArray(books)) continue
        const names = books.filter((name): name is string => typeof name === 'string' && !!name.trim())
        if (names.length) owned[chatId] = names
    }
    return owned
}

/** Read a per-chat name map defensively, as `readCampaignBooks` does. */
/**
 * A message count, or `0` for the whole chat.
 *
 * Rounded and floored at zero: this decides how much history a model is shown,
 * and a negative or fractional slice would either read as "all" by accident or
 * throw somewhere far from here.
 */
export function readLookback(value: unknown): number {
    const n = Number(value)
    if (!Number.isFinite(n) || n <= 0) return 0
    return Math.floor(n)
}

/**
 * A connection profile id, or `''` for "whatever the host would have used".
 *
 * Empty is the meaningful default rather than a missing value: an install with
 * one connection, or a user who has not chosen, must keep working exactly as
 * before. A stored id that no longer exists is *not* corrected here — the host
 * is the only thing that knows which ids are real, and silently rewriting a
 * user's choice because we could not verify it would be worse than passing it
 * on and letting the call fail loudly.
 */
/** The second pass's preferences (72b), read into `target` from `source` where present. */
function readSecondPassPrefs(source: Record<string, unknown>, target: Partial<UiPrefs>): void {
    for (const key of ['frameworkEnabled', 'agentEnabled', 'trackerSwipeRollback', 'agentSwipeRollback', 'portraitsEnabled', 'npcRelationshipToast'] as const) {
        if (source[key] !== undefined) target[key] = source[key] !== false
    }
    // Off unless true (73c): the legacy's `fullReviewStateMode` ships off.
    if (source.trackerFullReviewMode !== undefined) target.trackerFullReviewMode = source.trackerFullReviewMode === true
    // Show Location Images (80): off unless true, as Multihog ships it.
    if (source.locationImages !== undefined) target.locationImages = source.locationImages === true
    // The lorebooks into the tracker (73h): the switch off unless true, the filter a list of names, trimmed and deduplicated.
    if (source.trackerInjectLorebooks !== undefined) target.trackerInjectLorebooks = source.trackerInjectLorebooks === true
    if (source.trackerLorebookFilter !== undefined) target.trackerLorebookFilter = readExampleKeys(source.trackerLorebookFilter)
    if (source.legacyDiceNaming !== undefined) target.legacyDiceNaming = source.legacyDiceNaming === true
    if (source.inventoryShowTotal !== undefined) target.inventoryShowTotal = source.inventoryShowTotal === true
    if (source.inventoryWorthMode !== undefined) target.inventoryWorthMode = readInventoryWorthMode(source.inventoryWorthMode)
    if (source.agentLookbackMode !== undefined) target.agentLookbackMode = readAgentLookbackMode(source.agentLookbackMode)
    if (source.trackerHistoryStates !== undefined) target.trackerHistoryStates = readBounded(source.trackerHistoryStates, DEFAULT_TRACKER_HISTORY_STATES, 1, MAX_TRACKER_HISTORY_STATES)
    if (source.npcMajorWords !== undefined) target.npcMajorWords = readBounded(source.npcMajorWords, DEFAULT_NPC_MAJOR_WORDS, 1, MAX_NPC_WORDS)
    if (source.npcMinorWords !== undefined) target.npcMinorWords = readBounded(source.npcMinorWords, DEFAULT_NPC_MINOR_WORDS, 1, MAX_NPC_WORDS)
    if (source.mapArchitectConnectionId !== undefined) target.mapArchitectConnectionId = readConnectionId(source.mapArchitectConnectionId)
    if (source.mapUpdaterConnectionId !== undefined) target.mapUpdaterConnectionId = readConnectionId(source.mapUpdaterConnectionId)
    if (typeof source.narratorCardName === 'string') target.narratorCardName = source.narratorCardName.trim().slice(0, 120) || DEFAULT_NARRATOR_CARD_NAME
    // The terminal (71b).
    if (source.terminalDrafts !== undefined) {
        const raw = source.terminalDrafts && typeof source.terminalDrafts === 'object' ? (source.terminalDrafts as Record<string, unknown>) : {}
        const drafts = emptyTerminalDrafts()
        for (const key of TERMINAL_SOURCES) if (typeof raw[key] === 'string') drafts[key] = raw[key].slice(0, 4000)
        target.terminalDrafts = drafts
    }
    for (const key of ['mapUpdaterDirectLookback', 'mapEvolutionDirectLookback', 'mapArchitectDirectLookback'] as const) {
        if (source[key] !== undefined) target[key] = readDirectLookback(source[key], DEFAULT_TERMINAL_DIRECT_LOOKBACK, MAX_TERMINAL_DIRECT_LOOKBACK)
    }
    if (source.agentTerminalTab !== undefined) target.agentTerminalTab = (TERMINAL_SOURCES as readonly string[]).includes(String(source.agentTerminalTab)) ? source.agentTerminalTab as TerminalSource : 'lorebook_agent'
    if (typeof source.trackerUserPromptSuffix === 'string') target.trackerUserPromptSuffix = source.trackerUserPromptSuffix
    // The agent's tools (71c).
    if (source.agentPaused !== undefined) target.agentPaused = source.agentPaused === true
    if (source.agentCleanupUseThreshold !== undefined) target.agentCleanupUseThreshold = source.agentCleanupUseThreshold !== false
    if (source.agentCleanupThreshold !== undefined) target.agentCleanupThreshold = readBounded(source.agentCleanupThreshold, DEFAULT_CLEANUP_THRESHOLD, MIN_CLEANUP_THRESHOLD, MAX_CLEANUP_THRESHOLD)
    if (source.agentCleanupEvery !== undefined) target.agentCleanupEvery = readBounded(source.agentCleanupEvery, DEFAULT_CLEANUP_EVERY, 0, MAX_CLEANUP_EVERY)
    if (source.agentAuditTokens !== undefined) target.agentAuditTokens = readBounded(source.agentAuditTokens, DEFAULT_AUDIT_TOKENS, MIN_AUDIT_TOKENS, MAX_AUDIT_TOKENS)
}

export function readConnectionId(value: unknown): string {
    return typeof value === 'string' ? value.trim() : ''
}

/** One of the two windows, or the recommended one for anything unrecognised. */
/**
 * A send-bar window, floored at zero and capped as the legacy's inputs are.
 *
 * Zero is allowed, unlike the automatic pass's window: an instructed pass may
 * be told to read nothing and act on the instruction alone.
 */
export function readDirectLookback(value: unknown, fallback: number, max: number): number {
    if (value === undefined || value === null || value === '') return fallback
    const n = Number(value)
    if (!Number.isFinite(n)) return fallback
    return Math.min(Math.max(Math.floor(n), 0), max)
}

/** The scene's window (52): a whole number of replies, one to twenty; anything else is the default. */
/** The trigger, the legacy's default for anything else (49). */
export function readScenePictureTrigger(value: unknown): ScenePictureTrigger {
    return SCENE_PICTURE_TRIGGERS.includes(value as ScenePictureTrigger) ? (value as ScenePictureTrigger) : DEFAULT_SCENE_PICTURE_TRIGGER
}

/** N for the every-N trigger (49): a whole number, 1 to 50. */
export function readScenePictureEveryN(value: unknown): number {
    if (value === undefined || value === null || value === '') return DEFAULT_SCENE_PICTURE_EVERY_N
    const n = Number(value)
    if (!Number.isFinite(n)) return DEFAULT_SCENE_PICTURE_EVERY_N
    return Math.min(Math.max(Math.floor(n), 1), MAX_SCENE_PICTURE_EVERY_N)
}

/** The portrait preferences (61), read into `target` from `source` where present. */
function readPortraitPrefs(source: Record<string, unknown>, target: Partial<UiPrefs>): void {
    for (const key of ['portraitAutoPlayer', 'portraitAutoParty', 'portraitAutoEnemies', 'portraitAutoNpcs', 'portraitStoryLookback'] as const) {
        if (source[key] !== undefined) target[key] = source[key] === true
    }
    if (source.portraitStoryLookbackCount !== undefined) target.portraitStoryLookbackCount = readBounded(source.portraitStoryLookbackCount, DEFAULT_PORTRAIT_LOOKBACK, 0, MAX_PORTRAIT_LOOKBACK)
    if (source.portraitConnectionId !== undefined) target.portraitConnectionId = readConnectionId(source.portraitConnectionId)
    if (source.portraitPromptConnectionId !== undefined) target.portraitPromptConnectionId = readConnectionId(source.portraitPromptConnectionId)
}

/** The five picture preferences (49), read into `target` from `source` where present. */
function readScenePicturePrefs(source: Record<string, unknown>, target: Partial<UiPrefs>): void {
    if (source.scenePictureAuto !== undefined) target.scenePictureAuto = source.scenePictureAuto === true
    if (source.scenePictureTrigger !== undefined) target.scenePictureTrigger = readScenePictureTrigger(source.scenePictureTrigger)
    if (source.scenePictureEveryN !== undefined) target.scenePictureEveryN = readScenePictureEveryN(source.scenePictureEveryN)
    if (source.scenePicturePresentNpcs !== undefined) target.scenePicturePresentNpcs = source.scenePicturePresentNpcs !== false
    if (source.scenePictureConnectionId !== undefined) target.scenePictureConnectionId = typeof source.scenePictureConnectionId === 'string' ? source.scenePictureConnectionId.trim() : ''
    if (source.portraitSkipPromptDialog !== undefined) target.portraitSkipPromptDialog = source.portraitSkipPromptDialog === true
    if (source.portraitLocationBackground !== undefined) target.portraitLocationBackground = source.portraitLocationBackground === true
    if (source.attachBooksToCard !== undefined) target.attachBooksToCard = source.attachBooksToCard !== false
    if (source.choicesDisplayRegex !== undefined) target.choicesDisplayRegex = source.choicesDisplayRegex !== false
    if (source.debugLogging !== undefined) target.debugLogging = source.debugLogging === true
    if (source.autoUpdatePrompts !== undefined) target.autoUpdatePrompts = source.autoUpdatePrompts !== false
    if (source.attachBooksTarget !== undefined) target.attachBooksTarget = readAttachBooksTarget(source.attachBooksTarget)
}

export function readSceneLookback(value: unknown): number {
    if (value === undefined || value === null || value === '') return DEFAULT_SCENE_LOOKBACK
    const n = Number(value)
    if (!Number.isFinite(n)) return DEFAULT_SCENE_LOOKBACK
    return Math.min(Math.max(Math.floor(n), 1), MAX_SCENE_LOOKBACK)
}

export function readLookbackMode(value: unknown): TrackerLookbackMode {
    return value === 'fixed' ? 'fixed' : DEFAULT_LOOKBACK_MODE
}

/** The panel's layout (47b, 47c). Anything unknown is the classic one tab. */
export function readLayout(value: unknown): PanelLayout {
    return value === 'classic' || value === 'tabs' || value === 'widgets' ? value : DEFAULT_LAYOUT
}

/**
 * Widget positions, dropping anything that is not a name with two finite
 * numbers. A nonsense position would put a widget off screen with no way
 * to drag it back, so an unreadable one means the widget's default.
 */
export function readWidgetPositions(source: unknown): WidgetPositions {
    const positions: WidgetPositions = {}
    if (!source || typeof source !== 'object') return positions
    for (const [name, value] of Object.entries(source as Record<string, unknown>)) {
        if (!name || !value || typeof value !== 'object') continue
        const { x, y } = value as { x?: unknown; y?: unknown }
        if (typeof x !== 'number' || typeof y !== 'number' || !Number.isFinite(x) || !Number.isFinite(y)) continue
        positions[name] = { x: Math.round(x), y: Math.round(y) }
    }
    return positions
}

/** Which widgets are folded (57): a boolean per name; anything else dropped. */
export function readWidgetMinimized(source: unknown): WidgetMinimized {
    const minimized: WidgetMinimized = {}
    if (!source || typeof source !== 'object' || Array.isArray(source)) return minimized
    for (const [name, value] of Object.entries(source as Record<string, unknown>)) {
        if (name && typeof value === 'boolean') minimized[name] = value
    }
    return minimized
}

/** The widgets' sizes, each a pair of finite numbers floored at the minimum; anything else dropped. */
export function readWidgetSizes(source: unknown): WidgetSizes {
    const sizes: WidgetSizes = {}
    if (!source || typeof source !== 'object') return sizes
    for (const [name, value] of Object.entries(source as Record<string, unknown>)) {
        if (!name || !value || typeof value !== 'object') continue
        const { width, height } = value as { width?: unknown; height?: unknown }
        if (typeof width !== 'number' || typeof height !== 'number' || !Number.isFinite(width) || !Number.isFinite(height)) continue
        sizes[name] = {
            width: Math.max(MIN_WIDGET_SIZE.width, Math.round(width)),
            height: Math.max(MIN_WIDGET_SIZE.height, Math.round(height)),
        }
    }
    return sizes
}

/**
 * A fixed window size, floored at one.
 *
 * Zero would send the extractor no narrative at all, which reads as a broken
 * tracker rather than a fast one — the same reason zero is not "off" for the
 * agent's turn budget.
 */
export function readLookbackCount(value: unknown): number {
    if (value === undefined || value === null || value === '') return DEFAULT_LOOKBACK_COUNT
    const n = Number(value)
    if (!Number.isFinite(n)) return DEFAULT_LOOKBACK_COUNT
    return Math.min(Math.max(Math.floor(n), 1), 50)
}

/**
 * A turn budget, defended against a hand-edited file.
 *
 * Unlike the cadence, **zero is not a meaning here**. "Run the agent zero
 * turns" is not something anybody wants; it would make every pass report that
 * it used its budget without committing, which reads as a broken agent rather
 * than a switched-off one. So nonsense falls back to the default and a real
 * number is clamped into a usable range instead.
 *
 * The ceiling is the loop's own hard call ceiling: a budget above it could
 * never be spent, so offering one would be a lie.
 */
export function readMaxTurns(value: unknown): number {
    if (value === undefined || value === null || value === '') return DEFAULT_MAX_TURNS
    const n = Number(value)
    if (!Number.isFinite(n)) return DEFAULT_MAX_TURNS
    return Math.min(Math.max(Math.floor(n), 1), HARD_CALL_CEILING)
}

/**
 * The cadence, defended against a hand-edited file.
 *
 * A negative or nonsense value means off rather than "every reply": the
 * failure that costs nothing is the one to prefer when the alternative writes
 * to a campaign on every turn.
 */
export function readRunEvery(value: unknown): number {
    if (value === undefined || value === null || value === '') return DEFAULT_RUN_EVERY
    const n = Number(value)
    if (!Number.isFinite(n) || n <= 0) return 0
    return Math.min(Math.floor(n), MAX_RUN_EVERY)
}

/** Watermarks, dropping anything that is not a chat id and a count. */
export function readWatermarks(source: unknown): Record<string, number> {
    const marks: Record<string, number> = {}
    if (!source || typeof source !== 'object') return marks
    for (const [chatId, value] of Object.entries(source as Record<string, unknown>)) {
        const n = Number(value)
        if (!chatId || !Number.isFinite(n) || n < 0) continue
        marks[chatId] = Math.floor(n)
    }
    return marks
}

export function readCampaignNames(source: unknown): Record<string, string> {
    const names: Record<string, string> = {}
    if (!source || typeof source !== 'object') return names
    for (const [chatId, name] of Object.entries(source as Record<string, unknown>)) {
        if (!chatId || typeof name !== 'string' || !name.trim()) continue
        names[chatId] = name.trim()
    }
    return names
}

export function readPrefs(stored: unknown): UiPrefs {
    const prefs: UiPrefs = { ...DEFAULT_PREFS }
    if (!stored || typeof stored !== 'object') return prefs

    const source = stored as Partial<PrefsRecord>
    if (typeof source.messageCards === 'boolean') prefs.messageCards = source.messageCards
    if (typeof source.partyCompact === 'boolean') prefs.partyCompact = source.partyCompact
    if (source.campaignBooks) prefs.campaignBooks = readCampaignBooks(source.campaignBooks)
    if (source.campaignNames) prefs.campaignNames = readCampaignNames(source.campaignNames)
    if (Number.isFinite(source.agentLookback)) prefs.agentLookback = readLookback(source.agentLookback)
    if (source.agentMaxTurns !== undefined) prefs.agentMaxTurns = readMaxTurns(source.agentMaxTurns)
    if (source.trackerConnectionId !== undefined) {
        prefs.trackerConnectionId = readConnectionId(source.trackerConnectionId)
    }
    if (source.trackerLookbackMode !== undefined) {
        prefs.trackerLookbackMode = readLookbackMode(source.trackerLookbackMode)
    }
    if (source.layout !== undefined) prefs.layout = readLayout(source.layout)
    if (source.trackerTheme !== undefined) prefs.trackerTheme = readThemeId(source.trackerTheme)
    if (source.trackerFontSize !== undefined) prefs.trackerFontSize = readFontSize(source.trackerFontSize)
    if (source.settingsFontSize !== undefined) prefs.settingsFontSize = readFontSize(source.settingsFontSize)
    if (source.customTheme !== undefined) prefs.customTheme = readCustomTheme(source.customTheme)
    if (source.savedThemes !== undefined) prefs.savedThemes = readSavedThemes(source.savedThemes)
    if (source.dayNightCycle !== undefined) prefs.dayNightCycle = source.dayNightCycle === true
    if (source.xpBarAtBottom !== undefined) prefs.xpBarAtBottom = source.xpBarAtBottom === true
    if (source.animateAllCustomBarChanges !== undefined) prefs.animateAllCustomBarChanges = source.animateAllCustomBarChanges === true
    if (source.panelLayoutMode === 'tabs' || source.panelLayoutMode === 'stack') prefs.panelLayoutMode = source.panelLayoutMode
    if (typeof source.trackerActiveTab === 'string') prefs.trackerActiveTab = source.trackerActiveTab.slice(0, 200)
    if (source.displayGroupsEnabled !== undefined) prefs.displayGroupsEnabled = source.displayGroupsEnabled === true
    if (source.displayGroupsShowGaps !== undefined) prefs.displayGroupsShowGaps = source.displayGroupsShowGaps === true
    if (source.displayGroups !== undefined) prefs.displayGroups = readDisplayGroups(source.displayGroups)
    if (source.mapTheme !== undefined) prefs.mapTheme = readMapTheme(source.mapTheme)
    if (source.savedMapThemePresets !== undefined) prefs.savedMapThemePresets = readSavedMapThemePresets(source.savedMapThemePresets)
    if (source.activeMapThemePresetId !== undefined) prefs.activeMapThemePresetId = readMapThemePresetId(source.activeMapThemePresetId)
    if (source.trackerBackdrop !== undefined) prefs.trackerBackdrop = readBackdrop(source.trackerBackdrop)
    if (source.settingsBackdrop !== undefined) prefs.settingsBackdrop = readBackdrop(source.settingsBackdrop)
    prefs.widgetPositions = readWidgetPositions(source.widgetPositions)
    prefs.widgetSizes = readWidgetSizes(source.widgetSizes)
    prefs.widgetMinimized = readWidgetMinimized(source.widgetMinimized)
    if (source.trackerLookbackCount !== undefined) {
        prefs.trackerLookbackCount = readLookbackCount(source.trackerLookbackCount)
    }
    if (source.trackerRunEvery !== undefined) {
        prefs.trackerRunEvery = readTrackerRunEvery(source.trackerRunEvery)
    }
    prefs.trackerWatermarks = readWatermarks(source.trackerWatermarks)
    if (source.agentConnectionId !== undefined) {
        prefs.agentConnectionId = readConnectionId(source.agentConnectionId)
    }
    if (source.agentRunEvery !== undefined) prefs.agentRunEvery = readRunEvery(source.agentRunEvery)
    prefs.agentWatermarks = readWatermarks(source.agentWatermarks)
    if (source.trackerDirectLookback !== undefined) {
        prefs.trackerDirectLookback = readDirectLookback(source.trackerDirectLookback, DEFAULT_TRACKER_DIRECT_LOOKBACK, MAX_TRACKER_DIRECT_LOOKBACK)
    }
    if (source.sceneLookback !== undefined) prefs.sceneLookback = readSceneLookback(source.sceneLookback)
    readScenePicturePrefs(source, prefs)
    readPortraitPrefs(source, prefs)
    readSecondPassPrefs(source, prefs)
    if (source.agentDirectLookback !== undefined) {
        prefs.agentDirectLookback = readDirectLookback(source.agentDirectLookback, DEFAULT_AGENT_DIRECT_LOOKBACK, MAX_AGENT_DIRECT_LOOKBACK)
    }
    if (source.wizardLookback !== undefined) {
        prefs.wizardLookback = readDirectLookback(source.wizardLookback, DEFAULT_WIZARD_LOOKBACK, MAX_WIZARD_LOOKBACK)
    }
    if (typeof source.wizardInjectMemo === 'boolean') prefs.wizardInjectMemo = source.wizardInjectMemo
    if (typeof source.wizardLookbackAll === 'boolean') prefs.wizardLookbackAll = source.wizardLookbackAll
    if (typeof source.wizardInjectLore === 'boolean') prefs.wizardInjectLore = source.wizardInjectLore
    if (typeof source.wizardInjectModulePrompts === 'boolean') prefs.wizardInjectModulePrompts = source.wizardInjectModulePrompts
    if (source.wizardModuleExampleKeys !== undefined) prefs.wizardModuleExampleKeys = readExampleKeys(source.wizardModuleExampleKeys)
    if (typeof source.wizardSystemPrompt === 'string') prefs.wizardSystemPrompt = source.wizardSystemPrompt
    if (typeof source.worldProgressionEnabled === 'boolean') prefs.worldProgressionEnabled = source.worldProgressionEnabled
    if (source.worldProgressionIntervalHours !== undefined) prefs.worldProgressionIntervalHours = readBounded(source.worldProgressionIntervalHours, DEFAULT_WORLD_INTERVAL_HOURS, 1, MAX_WORLD_INTERVAL_HOURS)
    if (source.worldProgressionKeepActive !== undefined) prefs.worldProgressionKeepActive = readBounded(source.worldProgressionKeepActive, 1, 1, MAX_WORLD_KEEP_ACTIVE)
    if (source.worldProgressionLookback !== undefined) prefs.worldProgressionLookback = readBounded(source.worldProgressionLookback, DEFAULT_WORLD_LOOKBACK, 0, MAX_WORLD_LOOKBACK)
    if (source.worldProgressionHistoryLookback !== undefined) prefs.worldProgressionHistoryLookback = readBounded(source.worldProgressionHistoryLookback, 0, 0, 100)
    if (source.worldProgressionLocationsPerReport !== undefined) prefs.worldProgressionLocationsPerReport = readBounded(source.worldProgressionLocationsPerReport, DEFAULT_WORLD_LOCATIONS, 1, MAX_WORLD_LOCATIONS)
    if (typeof source.worldProgressionLocationRandomize === 'boolean') prefs.worldProgressionLocationRandomize = source.worldProgressionLocationRandomize
    if (typeof source.worldProgressionExclusionList === 'string') prefs.worldProgressionExclusionList = source.worldProgressionExclusionList
    if (typeof source.worldProgressionConsolidateEnabled === 'boolean') prefs.worldProgressionConsolidateEnabled = source.worldProgressionConsolidateEnabled
    if (source.worldProgressionConsolidateInterval !== undefined) prefs.worldProgressionConsolidateInterval = readBounded(source.worldProgressionConsolidateInterval, DEFAULT_WORLD_CONSOLIDATE_INTERVAL, 2, 50)
    readSkeletonPrefs(source, prefs)
    prefs.bars = readBarPrefs(source.bars)
    return prefs
}

/** The skeleton's eight keys, read the same way into a full record or a patch. */
function readSkeletonPrefs(source: Partial<Record<keyof UiPrefs, unknown>>, into: Partial<UiPrefs>): void {
    if (source.worldSkeletonFactions !== undefined) into.worldSkeletonFactions = readBounded(source.worldSkeletonFactions, DEFAULT_SKELETON_FACTIONS, 0, MAX_SKELETON_COUNT)
    if (source.worldSkeletonLocations !== undefined) into.worldSkeletonLocations = readBounded(source.worldSkeletonLocations, DEFAULT_SKELETON_LOCATIONS, 0, MAX_SKELETON_COUNT)
    if (source.worldSkeletonConflicts !== undefined) into.worldSkeletonConflicts = readBounded(source.worldSkeletonConflicts, DEFAULT_SKELETON_CONFLICTS, 0, MAX_SKELETON_COUNT)
    if (typeof source.worldSkeletonSystemPrompt === 'string') into.worldSkeletonSystemPrompt = source.worldSkeletonSystemPrompt
    if (typeof source.worldSkeletonUseLorebooks === 'boolean') into.worldSkeletonUseLorebooks = source.worldSkeletonUseLorebooks
    if (typeof source.worldSkeletonLorebookOnly === 'boolean') into.worldSkeletonLorebookOnly = source.worldSkeletonLorebookOnly
    if (typeof source.worldSkeletonLorebookFilter === 'string') into.worldSkeletonLorebookFilter = source.worldSkeletonLorebookFilter
    if (typeof source.worldSkeletonUseExisting === 'boolean') into.worldSkeletonUseExisting = source.worldSkeletonUseExisting
    if (source.worldSkeletonSourceLookback !== undefined) into.worldSkeletonSourceLookback = readBounded(source.worldSkeletonSourceLookback, DEFAULT_SKELETON_SOURCE_LOOKBACK, 1, MAX_SKELETON_SOURCE_LOOKBACK)
    if (source.mapArchitectLookback !== undefined) into.mapArchitectLookback = readBounded(source.mapArchitectLookback, DEFAULT_MAP_ARCHITECT_LOOKBACK, 0, MAX_MAP_ARCHITECT_LOOKBACK)
    if (typeof source.mapArchitectSystemPrompt === 'string') into.mapArchitectSystemPrompt = source.mapArchitectSystemPrompt
    if (source.mapArchitectOpener === 'tool' || source.mapArchitectOpener === 'text') into.mapArchitectOpener = source.mapArchitectOpener
    if (typeof source.mapUpdaterEnabled === 'boolean') into.mapUpdaterEnabled = source.mapUpdaterEnabled
    if (typeof source.mapRevealAll === 'boolean') into.mapRevealAll = source.mapRevealAll
    if (source.relationshipMax !== undefined) into.relationshipMax = normalizeRelationshipMax(source.relationshipMax)
    if (source.relationshipMode !== undefined) into.relationshipMode = normalizeRelationshipMode(source.relationshipMode)
    if (typeof source.relationshipTrackerPrompt === 'string') into.relationshipTrackerPrompt = source.relationshipTrackerPrompt
    if (source.mapUpdaterRunEvery !== undefined) into.mapUpdaterRunEvery = readBounded(source.mapUpdaterRunEvery, DEFAULT_MAP_UPDATER_RUN_EVERY, 1, MAX_MAP_UPDATER_RUN_EVERY)
    if (source.mapUpdaterLookback !== undefined) into.mapUpdaterLookback = readBounded(source.mapUpdaterLookback, DEFAULT_MAP_UPDATER_LOOKBACK, 1, MAX_MAP_UPDATER_LOOKBACK)
    if (typeof source.mapUpdaterSystemPrompt === 'string') into.mapUpdaterSystemPrompt = source.mapUpdaterSystemPrompt
    if (typeof source.mapEvolutionEnabled === 'boolean') into.mapEvolutionEnabled = source.mapEvolutionEnabled
    if (source.mapEvolutionIntervalHours !== undefined) into.mapEvolutionIntervalHours = readBounded(source.mapEvolutionIntervalHours, DEFAULT_MAP_EVOLUTION_INTERVAL_HOURS, 1, MAX_MAP_EVOLUTION_INTERVAL_HOURS)
    if (source.mapEvolutionOnSiteIntervalHours !== undefined) into.mapEvolutionOnSiteIntervalHours = readBounded(source.mapEvolutionOnSiteIntervalHours, DEFAULT_MAP_EVOLUTION_ON_SITE_HOURS, 0, MAX_MAP_EVOLUTION_INTERVAL_HOURS)
    if (source.mapEvolutionOnSiteIntervalMinutes !== undefined) into.mapEvolutionOnSiteIntervalMinutes = readBounded(source.mapEvolutionOnSiteIntervalMinutes, 0, 0, 59)
    if (source.mapEvolutionOnSitePreset === 'dynamic' || source.mapEvolutionOnSitePreset === 'standard') into.mapEvolutionOnSitePreset = source.mapEvolutionOnSitePreset
    if (source.mapEvolutionScope === 'active' || source.mapEvolutionScope === 'count' || source.mapEvolutionScope === 'all' || source.mapEvolutionScope === 'selected') into.mapEvolutionScope = source.mapEvolutionScope
    if (source.mapEvolutionCount !== undefined) into.mapEvolutionCount = readBounded(source.mapEvolutionCount, DEFAULT_MAP_EVOLUTION_COUNT, 0, MAX_MAP_EVOLUTION_COUNT)
    if (typeof source.mapEvolutionRandomize === 'boolean') into.mapEvolutionRandomize = source.mapEvolutionRandomize
    if (typeof source.mapEvolutionSelectedRoots === 'string') into.mapEvolutionSelectedRoots = source.mapEvolutionSelectedRoots
    if (source.mapEvolutionWorldReportLookback !== undefined) into.mapEvolutionWorldReportLookback = readBounded(source.mapEvolutionWorldReportLookback, DEFAULT_MAP_EVOLUTION_REPORT_LOOKBACK, 1, MAX_MAP_EVOLUTION_REPORT_LOOKBACK)
    if (typeof source.mapEvolutionSystemPrompt === 'string') into.mapEvolutionSystemPrompt = source.mapEvolutionSystemPrompt
    if (typeof source.mapEvolutionCompressEnabled === 'boolean') into.mapEvolutionCompressEnabled = source.mapEvolutionCompressEnabled
    if (source.mapEvolutionCompressThreshold !== undefined) into.mapEvolutionCompressThreshold = readBounded(source.mapEvolutionCompressThreshold, DEFAULT_MAP_EVOLUTION_COMPRESS_THRESHOLD, MIN_MAP_EVOLUTION_COMPRESS_THRESHOLD, MAX_MAP_EVOLUTION_COMPRESS_THRESHOLD)
    if (source.mapEvolutionNarratorCommitTokens !== undefined) into.mapEvolutionNarratorCommitTokens = readBounded(source.mapEvolutionNarratorCommitTokens, DEFAULT_MAP_EVOLUTION_NARRATOR_TOKENS, MIN_MAP_EVOLUTION_NARRATOR_TOKENS, MAX_MAP_EVOLUTION_NARRATOR_TOKENS)
    if (source.mapEvolutionLookback !== undefined) into.mapEvolutionLookback = readBounded(source.mapEvolutionLookback, DEFAULT_MAP_EVOLUTION_LOOKBACK, 0, MAX_MAP_EVOLUTION_LOOKBACK)
    if (source.mapEvolutionConnectionId !== undefined) into.mapEvolutionConnectionId = readConnectionId(source.mapEvolutionConnectionId)
    if (source.creatorDraft !== undefined) into.creatorDraft = readCreatorDraft(source.creatorDraft)
    if (source.creatorPresets !== undefined) into.creatorPresets = readCreatorPresets(source.creatorPresets)
    if (source.creatorLevel !== undefined) into.creatorLevel = readCreatorLevel(source.creatorLevel)
    if (source.creatorGearTier !== undefined) into.creatorGearTier = readCreatorGearTier(source.creatorGearTier)
    if (typeof source.creatorCombatScalingGuide === 'boolean') into.creatorCombatScalingGuide = source.creatorCombatScalingGuide
    if (typeof source.creatorInitialDate === 'string') into.creatorInitialDate = source.creatorInitialDate.trim() || 'Day 1'
    if (typeof source.creatorInitialTime === 'string') into.creatorInitialTime = source.creatorInitialTime.trim() || '08:00 AM'
    if (source.creatorConnectionId !== undefined) into.creatorConnectionId = readConnectionId(source.creatorConnectionId)
    if (source.narratorConnectionSeen !== undefined) into.narratorConnectionSeen = readConnectionId(source.narratorConnectionSeen)
    // Zero is blank; a number is whole and capped where no model's limit lies (89).
    if (source.passMaxTokens !== undefined) into.passMaxTokens = readBounded(source.passMaxTokens, 0, 0, MAX_PASS_MAX_TOKENS)
    if (typeof source.creatorGenre === 'string') into.creatorGenre = ['fantasy', 'realistic', 'scifi', 'horror'].includes(source.creatorGenre) ? source.creatorGenre : 'fantasy'
    if (typeof source.creatorSendStarter === 'boolean') into.creatorSendStarter = source.creatorSendStarter
    if (typeof source.creatorInstantRandomLevel === 'boolean') into.creatorInstantRandomLevel = source.creatorInstantRandomLevel
    if (typeof source.creatorPlayerCard === 'boolean') into.creatorPlayerCard = source.creatorPlayerCard
    if (typeof source.creatorPersona === 'boolean') into.creatorPersona = source.creatorPersona
    if (source.creatorCardWords !== undefined) into.creatorCardWords = normalizeCardWords(source.creatorCardWords)
    if (source.npcAddAsIsMode !== undefined) into.npcAddAsIsMode = source.npcAddAsIsMode === 'literal' ? 'literal' : 'ai_review'
    if (source.creatorWaysDraft !== undefined) {
        const draft = source.creatorWaysDraft as Record<string, unknown> | null
        into.creatorWaysDraft = draft && typeof draft === 'object' ? { name: typeof draft.name === 'string' ? draft.name : '', instructions: typeof draft.instructions === 'string' ? draft.instructions : '' } : null
    }
}

/** Keep only the keys that are really preferences, and only the right types. */
export function readPrefsPatch(patch: unknown): Partial<UiPrefs> {
    const clean: Partial<UiPrefs> = {}
    if (!patch || typeof patch !== 'object') return clean

    const source = patch as Partial<UiPrefs>
    if (typeof source.messageCards === 'boolean') clean.messageCards = source.messageCards
    if (typeof source.partyCompact === 'boolean') clean.partyCompact = source.partyCompact
    if (source.bars && typeof source.bars === 'object') clean.bars = source.bars
    if (source.campaignBooks !== undefined) clean.campaignBooks = readCampaignBooks(source.campaignBooks)
    if (source.campaignNames !== undefined) clean.campaignNames = readCampaignNames(source.campaignNames)
    if (source.agentLookback !== undefined) clean.agentLookback = readLookback(source.agentLookback)
    if (source.agentMaxTurns !== undefined) clean.agentMaxTurns = readMaxTurns(source.agentMaxTurns)
    if (source.trackerConnectionId !== undefined) {
        clean.trackerConnectionId = readConnectionId(source.trackerConnectionId)
    }
    if (source.trackerLookbackMode !== undefined) {
        clean.trackerLookbackMode = readLookbackMode(source.trackerLookbackMode)
    }
    if (source.layout !== undefined) clean.layout = readLayout(source.layout)
    if (source.trackerTheme !== undefined) clean.trackerTheme = readThemeId(source.trackerTheme)
    if (source.trackerFontSize !== undefined) clean.trackerFontSize = readFontSize(source.trackerFontSize)
    if (source.settingsFontSize !== undefined) clean.settingsFontSize = readFontSize(source.settingsFontSize)
    if (source.customTheme !== undefined) clean.customTheme = readCustomTheme(source.customTheme)
    if (source.savedThemes !== undefined) clean.savedThemes = readSavedThemes(source.savedThemes)
    if (source.dayNightCycle !== undefined) clean.dayNightCycle = source.dayNightCycle === true
    if (source.xpBarAtBottom !== undefined) clean.xpBarAtBottom = source.xpBarAtBottom === true
    if (source.animateAllCustomBarChanges !== undefined) clean.animateAllCustomBarChanges = source.animateAllCustomBarChanges === true
    if (source.panelLayoutMode === 'tabs' || source.panelLayoutMode === 'stack') clean.panelLayoutMode = source.panelLayoutMode
    if (typeof source.trackerActiveTab === 'string') clean.trackerActiveTab = source.trackerActiveTab.slice(0, 200)
    if (source.displayGroupsEnabled !== undefined) clean.displayGroupsEnabled = source.displayGroupsEnabled === true
    if (source.displayGroupsShowGaps !== undefined) clean.displayGroupsShowGaps = source.displayGroupsShowGaps === true
    if (source.displayGroups !== undefined) clean.displayGroups = readDisplayGroups(source.displayGroups)
    if (source.mapTheme !== undefined) clean.mapTheme = readMapTheme(source.mapTheme)
    if (source.savedMapThemePresets !== undefined) clean.savedMapThemePresets = readSavedMapThemePresets(source.savedMapThemePresets)
    if (source.activeMapThemePresetId !== undefined) clean.activeMapThemePresetId = readMapThemePresetId(source.activeMapThemePresetId)
    if (source.trackerBackdrop !== undefined) clean.trackerBackdrop = readBackdrop(source.trackerBackdrop)
    if (source.settingsBackdrop !== undefined) clean.settingsBackdrop = readBackdrop(source.settingsBackdrop)
    if (source.widgetPositions !== undefined) clean.widgetPositions = readWidgetPositions(source.widgetPositions)
    if (source.widgetSizes !== undefined) clean.widgetSizes = readWidgetSizes(source.widgetSizes)
    if (source.widgetMinimized !== undefined) clean.widgetMinimized = readWidgetMinimized(source.widgetMinimized)
    if (source.trackerLookbackCount !== undefined) {
        clean.trackerLookbackCount = readLookbackCount(source.trackerLookbackCount)
    }
    if (source.agentConnectionId !== undefined) {
        clean.agentConnectionId = readConnectionId(source.agentConnectionId)
    }
    if (source.trackerRunEvery !== undefined) {
        clean.trackerRunEvery = readTrackerRunEvery(source.trackerRunEvery)
    }
    if (source.trackerWatermarks !== undefined) {
        clean.trackerWatermarks = readWatermarks(source.trackerWatermarks)
    }
    if (source.agentRunEvery !== undefined) clean.agentRunEvery = readRunEvery(source.agentRunEvery)
    if (source.agentWatermarks !== undefined) clean.agentWatermarks = readWatermarks(source.agentWatermarks)
    if (source.trackerDirectLookback !== undefined) {
        clean.trackerDirectLookback = readDirectLookback(source.trackerDirectLookback, DEFAULT_TRACKER_DIRECT_LOOKBACK, MAX_TRACKER_DIRECT_LOOKBACK)
    }
    if (source.sceneLookback !== undefined) clean.sceneLookback = readSceneLookback(source.sceneLookback)
    readScenePicturePrefs(source, clean)
    readPortraitPrefs(source, clean)
    readSecondPassPrefs(source, clean)
    if (source.agentDirectLookback !== undefined) {
        clean.agentDirectLookback = readDirectLookback(source.agentDirectLookback, DEFAULT_AGENT_DIRECT_LOOKBACK, MAX_AGENT_DIRECT_LOOKBACK)
    }
    if (source.wizardLookback !== undefined) {
        clean.wizardLookback = readDirectLookback(source.wizardLookback, DEFAULT_WIZARD_LOOKBACK, MAX_WIZARD_LOOKBACK)
    }
    if (typeof source.wizardInjectMemo === 'boolean') clean.wizardInjectMemo = source.wizardInjectMemo
    if (typeof source.wizardLookbackAll === 'boolean') clean.wizardLookbackAll = source.wizardLookbackAll
    if (typeof source.wizardInjectLore === 'boolean') clean.wizardInjectLore = source.wizardInjectLore
    if (typeof source.wizardInjectModulePrompts === 'boolean') clean.wizardInjectModulePrompts = source.wizardInjectModulePrompts
    if (source.wizardModuleExampleKeys !== undefined) clean.wizardModuleExampleKeys = readExampleKeys(source.wizardModuleExampleKeys)
    if (typeof source.wizardSystemPrompt === 'string') clean.wizardSystemPrompt = source.wizardSystemPrompt
    if (typeof source.worldProgressionEnabled === 'boolean') clean.worldProgressionEnabled = source.worldProgressionEnabled
    if (source.worldProgressionIntervalHours !== undefined) clean.worldProgressionIntervalHours = readBounded(source.worldProgressionIntervalHours, DEFAULT_WORLD_INTERVAL_HOURS, 1, MAX_WORLD_INTERVAL_HOURS)
    if (source.worldProgressionKeepActive !== undefined) clean.worldProgressionKeepActive = readBounded(source.worldProgressionKeepActive, 1, 1, MAX_WORLD_KEEP_ACTIVE)
    if (source.worldProgressionLookback !== undefined) clean.worldProgressionLookback = readBounded(source.worldProgressionLookback, DEFAULT_WORLD_LOOKBACK, 0, MAX_WORLD_LOOKBACK)
    if (source.worldProgressionHistoryLookback !== undefined) clean.worldProgressionHistoryLookback = readBounded(source.worldProgressionHistoryLookback, 0, 0, 100)
    if (source.worldProgressionLocationsPerReport !== undefined) clean.worldProgressionLocationsPerReport = readBounded(source.worldProgressionLocationsPerReport, DEFAULT_WORLD_LOCATIONS, 1, MAX_WORLD_LOCATIONS)
    if (typeof source.worldProgressionLocationRandomize === 'boolean') clean.worldProgressionLocationRandomize = source.worldProgressionLocationRandomize
    if (typeof source.worldProgressionExclusionList === 'string') clean.worldProgressionExclusionList = source.worldProgressionExclusionList
    if (typeof source.worldProgressionConsolidateEnabled === 'boolean') clean.worldProgressionConsolidateEnabled = source.worldProgressionConsolidateEnabled
    if (source.worldProgressionConsolidateInterval !== undefined) clean.worldProgressionConsolidateInterval = readBounded(source.worldProgressionConsolidateInterval, DEFAULT_WORLD_CONSOLIDATE_INTERVAL, 2, 50)
    readSkeletonPrefs(source, clean)

    return clean
}

/**
 * Fold a bar patch into the bars already stored.
 *
 * Per bar rather than whole-map, so setting one bar's colour cannot drop
 * another's — and so a bar reset to nothing (`{}`) removes its entry instead of
 * leaving one that changes no pixel.
 */
export function mergeBarPrefs(current: BarPrefs, patch: unknown): BarPrefs {
    const merged: BarPrefs = { ...current }
    if (!patch || typeof patch !== 'object') return merged

    for (const [barId, value] of Object.entries(patch as Record<string, unknown>)) {
        if (!barId) continue
        const pref = readBarPref(value)
        if (pref) merged[barId] = pref
        else delete merged[barId]
    }
    return merged
}

/**
 * The per-user preference store.
 *
 * Writes are chained per user for the same reason the settings store chains
 * them: two patches in one tick must not both read-modify-write the same
 * starting state, or the second silently drops the first.
 */
export class PrefsStore {
    readonly #storage: PrefsStorage
    readonly #cache = new Map<string, UiPrefs>()
    readonly #writes = new Map<string, Promise<unknown>>()

    constructor(storage: PrefsStorage) {
        this.#storage = storage
    }

    #key(userId?: string): string {
        return userId ?? DEFAULT_USER
    }

    /**
     * Read a user's preferences.
     *
     * A missing or unreadable file is a fresh install, not an error, so it
     * gives back the defaults. Nothing here is important enough to fail a panel
     * draw over.
     */
    async load(userId?: string): Promise<UiPrefs> {
        const key = this.#key(userId)
        const cached = this.#cache.get(key)
        if (cached) return { ...cached, bars: { ...cached.bars } }

        let stored: unknown = null
        try {
            stored = await this.#storage.getJson<unknown>(PREFS_PATH, { fallback: null, userId })
        } catch {
            stored = null
        }

        const prefs = readPrefs(stored)
        this.#cache.set(key, prefs)
        return { ...prefs, bars: { ...prefs.bars } }
    }

    /** Change some preferences and keep the rest. Returns the new full set. */
    async patch(patch: unknown, userId?: string): Promise<UiPrefs> {
        const key = this.#key(userId)
        const clean = readPrefsPatch(patch)

        const chained = (this.#writes.get(key) ?? Promise.resolve())
            .catch(() => undefined)
            .then(async (): Promise<UiPrefs> => {
                const current = await this.load(userId)
                const next: UiPrefs = {
                    ...current,
                    ...clean,
                    bars: mergeBarPrefs(current.bars, clean.bars),
                }
                const record: PrefsRecord = { version: PREFS_VERSION, ...next }

                this.#cache.set(key, next)
                await this.#storage.setJson(PREFS_PATH, record, { indent: 2, userId })
                return next
            })

        this.#writes.set(key, chained)
        return chained.then((prefs) => ({ ...prefs, bars: { ...prefs.bars } }))
    }

    /**
     * The install's preferences to their defaults (72a, the factory reset),
     * keeping what belongs to a chat: the campaigns' names, the books they
     * own and the two watermarks, which say what the lorebooks already hold.
     */
    async resetInstall(userId?: string): Promise<UiPrefs> {
        const key = this.#key(userId)
        const chained = (this.#writes.get(key) ?? Promise.resolve())
            .catch(() => undefined)
            .then(async (): Promise<UiPrefs> => {
                const current = await this.load(userId)
                const next: UiPrefs = {
                    ...DEFAULT_PREFS,
                    bars: {},
                    campaignBooks: current.campaignBooks,
                    campaignNames: current.campaignNames,
                    trackerWatermarks: current.trackerWatermarks,
                    agentWatermarks: current.agentWatermarks,
                }
                const record: PrefsRecord = { version: PREFS_VERSION, ...next }
                this.#cache.set(key, next)
                await this.#storage.setJson(PREFS_PATH, record, { indent: 2, userId })
                return next
            })
        this.#writes.set(key, chained)
        return chained.then((prefs) => ({ ...prefs, bars: { ...prefs.bars } }))
    }

    /**
     * The preferences already in memory for a user, or nothing.
     *
     * For the interceptor only, which may not wait: a world report is injected
     * from what is cached, and a user whose preferences were never loaded gets
     * none this turn rather than a round trip.
     */
    snapshot(userId?: string): UiPrefs | undefined {
        return this.#cache.get(this.#key(userId))
    }

    /** Drop the cached preferences, so the next read comes from storage. */
    forget(userId?: string): void {
        this.#cache.delete(this.#key(userId))
    }
}

/** The picker's keys (73g): strings, trimmed, deduplicated, in the order given; anything else is none. */
/** A list of names or keys (73g, 73h): strings trimmed and deduplicated, anything else an empty list. */
function readExampleKeys(value: unknown): string[] {
    if (!Array.isArray(value)) return []
    return [...new Set(value.map((key) => String(key ?? '').trim()).filter(Boolean))]
}
